INSERT IGNORE INTO question (type,difficulty,stem,options_json,answer,score_points_json,analysis,source,fingerprint,status) VALUES
('SINGLE',2,'下面程序的运行结果是 String str1 = "hello";
String str2 = "he" + new String("llo");
System.err.println(str1 == str2);','[{"key": "A", "text": "true"}, {"key": "B", "text": "false"}, {"key": "C", "text": "exception"}, {"key": "D", "text": "无输出"}]','B',NULL,'这道题目考察了Java中字符串对象的创建和比较机制。在Java中,使用==比较字符串时比较的是对象的引用地址而不是内容。题目中的两个字符串虽然内容相同,但创建方式不同,导致它们指向不同的内存地址:str1 = "hello" 是字符串字面量,会直接在字符串常量池中创建。str2 = "he" + new String("llo") 的创建过程比较复杂:1. new String("llo")会在堆内存创建一个新的字符串对象2. "he"和这个新创建的字符串对象进行拼接3. 最终的拼接结果会在堆内存中创建一个新的String对象因此str1和str2虽然内容相同,但分别指向不同的内存地址,所以使用==比较时结果为false。其他选项分析:A错误:因为两个对象引用地址不同,不可能相等C错误:代码可以正常执行,不会抛出异常D错误:程序会正常输出false,而不是无输出如果要比较字符串的内容是否相同,应该使用equals()方法,而不是==运算符。 知识点：Java','MANUAL','c0e2a1f3be23a96417271b7e86ab499cc2ed54662f4367c67b828eb9bc0e3fa6',1),
('SINGLE',2,'在JVM调优中，以下关于JIT编译器的C1和C2的说法，哪项是正确的？','[{"key": "A", "text": "C1编译器进行更激进的优化，适合长时间运行的服务端应用"}, {"key": "B", "text": "C2编译器编译速度更快，适合快速启动的客户端应用"}, {"key": "C", "text": "分层编译（Tiered Compilation）结合C1和C2，先用C1快速编译，热点代码再用C2深度优化"}, {"key": "D", "text": "在GraalVM中，C2编译器被完全移除"}]','C',NULL,'分层编译是JDK 8+的默认策略，结合了C1和C2编译器的优势。C1（Client Compiler）编译速度快但优化程度低，用于快速编译；C2（Server Compiler）编译速度慢但优化激进，用于深度优化热点代码。A和B描述反了。D不完全正确，GraalVM中Graal编译器可以替代C2，但C2并非完全移除，标准JDK中仍然存在。 知识点：Java','MANUAL','f05764d5b9c48742649e21080539d9dad2bc1250290d1fa5e7ae9a1c8ca185c3',1),
('SINGLE',2,'如下的Java程序 public class Test { public static void main(String[] args) { System.out.println(args[0]); } } 若采用命令行“java Test one two three”调用，则程序输出的结果为：','[{"key": "A", "text": "Test"}, {"key": "B", "text": "one"}, {"key": "C", "text": "two"}, {"key": "D", "text": "java"}]','B',NULL,'这道题目考察了Java命令行参数的使用和程序执行过程的理解。在Java中，通过命令行执行Java程序时，命令行参数会被存储在main方法的String[] args数组中。其中：- java是启动Java程序的命令- Test是要执行的类名- 之后的"one two three"是传递给程序的命令行参数当使用"java Test one two three"执行程序时：- args[0]存储第一个参数"one"- args[1]存储第二个参数"two" - args[2]存储第三个参数"three"程序中System.out.println(args[0])输出的是args数组的第一个元素，即"one"，所以B选项是正确答案。分析其他选项：A错误：Test是类名，不是命令行参数C错误：two是第二个参数，存储在args[1]而不是args[0]中D错误：java是启动命令，不会作为参数传入程序需要注意的是：命令行中类名后面的参数才会被传入程序，而java命令和类名Test不会被当作参数处理。 知识点：Java','MANUAL','9f6ffe53a0dea4062e0592b5ed6c1620946b207e84758a3917662da3c5912d95',1),
('SINGLE',2,'以下代码使用Java Optional（假设每行代码独立执行），哪行会抛出异常？ 复制代码12345Optional<String> opt = Optional.ofNullable(null);String s1 = opt.orElse("default"); // line 1String s2 = opt.orElseGet(() -> "default"); // line 2String s3 = opt.orElseThrow(); // line 3String s4 = opt.or(() -> Optional.of("x")).get(); // line 4','[{"key": "A", "text": "line 1"}, {"key": "B", "text": "line 2"}, {"key": "C", "text": "line 3"}, {"key": "D", "text": "line 4"}]','C',NULL,'opt是一个空的Optional（ofNullable(null)）。line 1的orElse返回默认值"default"。line 2的orElseGet通过Supplier返回"default"。line 3的orElseThrow()在Optional为空时抛出NoSuchElementException。line 4的or()方法在Optional为空时返回另一个Optional.of("x")，然后get()返回"x"，不会抛异常。因此只有line 3会抛出异常。 知识点：Java','MANUAL','899d76274531ca229896a92759e08b51ab7d1b18e7953c929866222a531b6b66',1),
('SINGLE',2,'String s = new String("xyz");创建了几个StringObject？','[{"key": "A", "text": "两个或一个都有可能"}, {"key": "B", "text": "两个"}, {"key": "C", "text": "一个"}, {"key": "D", "text": "三个"}]','A',NULL,'答案: A 解析: 语句执行时会调用 new 在堆上创建一个 String 对象；字面量 "xyz" 位于字符串常量池，若此前未出现会在类加载时放入常量池（等效于本次“新增”一个），若已存在则复用。因此可能是两个（常量池1个+堆1个），也可能仅新建堆上这一个。 知识点：Java、安卓工程师、2018','MANUAL','3d8ecb05f3369a24f9f1b76f7de7fcd87575f508fbf72aadd255594efa6d2364',1),
('SINGLE',2,'在一个包含''部门ID''和''工资''的员工表中，如果要计算每个部门的平均工资并显示部门ID，以下哪个查询最正确？','[{"key": "A", "text": "SELECT 部门ID, AVG(工资) FROM 员工"}, {"key": "B", "text": "SELECT 部门ID, AVG(工资) FROM 员工 GROUP BY 部门ID"}, {"key": "C", "text": "SELECT AVG(工资) FROM 员工 WHERE 部门ID IS NOT NULL"}, {"key": "D", "text": "SELECT 部门ID, AVG(工资) WHERE 部门ID GROUP BY 部门ID"}]','B',NULL,'B选项正确使用了GROUP BY部门ID，从而实现对每个部门的分组，计算并显示每个部门的平均工资。A选项缺少GROUP BY子句，会导致错误，因为部门ID未聚合；C选项使用WHERE过滤了部门ID非NULL的行，但未选择部门ID字段，因此无法显示部门ID；D选项的WHERE子句语法错误，缺少条件表达式（例如，应为WHERE部门ID IS NOT NULL）。 知识点：SQL','MANUAL','c924e10c114c1bbdf3df9bde77a432097704b9f4e08d47942392ef7feeeaa941',1),
('SINGLE',2,'PreparedStatement 防止 SQL 注入的主要机制是？','[{"key": "A", "text": "参数自动转义"}, {"key": "B", "text": "编译时语法检查"}, {"key": "C", "text": "参数值与 SQL 指令分离处理"}, {"key": "D", "text": "强制事务隔离"}]','C',NULL,'PreparedStatement 防止 SQL 注入的主要机制是通过参数值与 SQL 指令分离处理。SQL 语句模板被预编译，参数值单独传递，数据库引擎将这些值视为数据而非可执行代码，从而有效阻止恶意 SQL 注入。选项 A（参数自动转义）错误，因为 PreparedStatement 不依赖自动转义机制，转义是另一种方法；选项 B（编译时语法检查）错误，编译时检查主要帮助识别语法错误，但非主要防止注入的机制；选项 D（强制事务隔离）错误，事务隔离处理并发控制，与 SQL 注入无关。题目和选项文字无错别字、专业名词无误（如 ''PreparedStatement''、''SQL 注入''、''事务隔离'' 均为标准术语），无逻辑矛盾，也无规则破坏错误。 知识点：SQL','MANUAL','dc60bd529b7f1ef6b0cae9182b7cf16564a2a168f23591bc8b074ecf62e93035',1),
('SINGLE',2,'有一张电话表（telephones），id是主键，send_id表示打电话人的id，receive_id表示接电话人的id，type表示电话是否打成功：


 


 
 
 
 还有一张用户表（users），id也是主键，is_blacklist列中的1 代表该用户是骚扰用户，即他的电话不会打成功，会被系统拦截。
 
 
 



 
 
 
 现要查询每天的正常用户给正常用户打电话，无法接通（可能是信号不好、电话欠费等原因导致）的概率，结果保留到小数点后两位，并按日期降序排列。比如上面示例就会得到如下结果
 
 
 



 
 
 
 (注意: sqlite 1/2得到的不是0.5，得到的是0，只有1*1.0/2才会得到0.5，sqlite四舍五入的函数为round) 
 
 
 下列sqlite查询语句正确的是（）','[{"key": "A", "text": "SELECT t.date, ROUND(SUM(CASE WHEN t.type = ''no_completed'' THEN 1 ELSE 0 END) * 1.0 / COUNT(t.type), 2) AS p FROM telephones t JOIN users u1 ON t.send_id = u1.id AND u1.is_blacklist = 0 JOIN users u2 ON t.receive_id = u2.id AND u2.is_blacklist = 0 GROUP BY t.date ORDER BY t.date DESC;"}, {"key": "B", "text": "SELECT t.date, ROUND(SUM(CASE t.type WHEN ''completed'' THEN 0 ELSE 1 END)* 1.0 / COUNT(t.type), 2) AS p FROM telephones AS t, users as u WHERE t.send_id = u.id AND t.receive_id = u.id AND u.is_blacklist = 0 GROUP BY t.date ORDER BY t.date DESC;"}, {"key": "C", "text": "SELECT t.date, ROUND(SUM(CASE WHEN t.type = ''no_completed'' THEN 1 ELSE 0 END) / COUNT(t.type), 2) AS p FROM telephones t JOIN users u1 ON t.send_id = u1.id AND u1.is_blacklist = 0 JOIN users u2 ON t.receive_id = u2.id AND u2.is_blacklist = 0 GROUP BY t.date ORDER BY t.date DESC;"}, {"key": "D", "text": "SELECT t.date, ROUND(SUM(CASE WHEN t.type = ''no_completed'' THEN 1 ELSE 0 END) * 1.0 / COUNT(t.type), 2) AS p FROM telephones JOIN users u1 ON t.send_id = u1.id AND u1.is_blacklist = 0 JOIN users u2 ON t.receive_id = u2.id AND u2.is_blacklist = 0 GROUP BY t.date ORDER BY t.date DESC;"}]','A',NULL,'本题考察知识点：sqlite的ROUND函数、聚合函数和CASE WHEN函数用法、JOIN...ON两表连接、分组排序操作 


 解题思路：


 
 
 根据题意， 分组的条件是每天，所以GROUP BY date；
 
 
 
 
 接着找到正常的打电话用户，即电话表中的send_id要等于users表中的id，且is_blacklist 要等于0才是正常电话用户；
 
 
 
 
 同理可找到正常的接电话用户；
 
 
 
 
 然后CASE WHEN 函数统计打电话不成功，即type = ''no_completed''的次数。再用聚合函数汇总以及ROUND函数进行概率计算；
 
 
 
 
 最后排序。
 
 


 因此，上面的A选项就是正确答案；


 
 
 
 B选项错在这一步“ WHERE t.send_id=u.id AND t.receive_id=u.id AND u.is_blacklist=0”，这样会筛选出一个空集出现；
 
 
 C选项错在审题不仔细，sqlite的ROUND函数必须要 * 1.0才能得到正确结果；
 
 
 D选项错在电话表连接用户表的时候，没有指定telephones AS t。以至于后面出现t.send_id会报错找不到表。
 
 
 
 知识点：数据库、SQL、概率论与数理统计、测试、后端开发、客户端开发、前端开发、人工智能/算法、数据、运维/技术支持','MANUAL','e10e453fe5022c9d93cc8e40fcab4bad093b7429638e825ede6a03ee02bfcd23',1),
